//! #3477 (slice C1): the Durable Object classes of a Worker's `Container`
//! instances.
//!
//! One file per Worker, `containers.ts`, re-exported from `index.ts` because
//! Cloudflare resolves a `class_name` against the exports of the Worker's
//! `main`. Each class is built by the runtime's `containerClass` from the
//! declaration's literals, so the generated file holds data and no logic, as
//! the agent classes' `serialiseAgentClass` wrapper does.

use bynk_check::worker_bindings::BindingSource;
use bynk_ts::{TsDecl, TsExpr, TsLit, TsProgram, TsStmt};

use crate::emitter::wrangler::WorkerBinding;

/// The Worker-relative specifier the runtime is imported from: the same depth
/// as `compose.ts` (`workers/<worker>/containers.ts`).
const RUNTIME_SPECIFIER: &str = "../../runtime.js";

/// The classes `index.ts` re-exports, one per container binding, in binding
/// order. Empty when the Worker has no container.
pub fn container_class_names(bindings: &[WorkerBinding]) -> Vec<String> {
    bindings
        .iter()
        .filter_map(|b| match &b.source {
            BindingSource::ContainerInstance { class_name, .. } => Some(class_name.clone()),
            _ => None,
        })
        .collect()
}

/// `containers.ts`, or `None` when the Worker has no container.
pub fn emit_containers_ts(bindings: &[WorkerBinding]) -> Option<TsProgram> {
    let containers: Vec<&BindingSource> = bindings
        .iter()
        .map(|b| &b.source)
        .filter(|s| matches!(s, BindingSource::ContainerInstance { .. }))
        .collect();
    if containers.is_empty() {
        return None;
    }
    let mut program = TsProgram::new();
    program.push(TsStmt::comment(
        "Generated by bynk — do not edit by hand.",
        None,
    ));
    program.push(TsStmt::comment(
        "Durable Object classes of the Worker's containers (#3477).",
        None,
    ));
    for stmt in crate::emitter::runtime_files::runtime_import_stmts(
        false,
        &["__containerClass".to_string()],
        RUNTIME_SPECIFIER,
    ) {
        program.push(stmt);
    }
    for source in containers {
        let BindingSource::ContainerInstance {
            capability,
            class_name,
            port,
            sleep_after,
            instance_type,
            forward,
            ..
        } = source
        else {
            continue;
        };
        let mut settings = vec![
            (
                "image".to_string(),
                TsExpr::Lit(TsLit::Str(capability.clone())),
            ),
            ("port".to_string(), TsExpr::Lit(TsLit::Num(port.to_string()))),
        ];
        if let Some(seconds) = sleep_after {
            settings.push((
                "sleepAfterSeconds".to_string(),
                TsExpr::Lit(TsLit::Num(seconds.to_string())),
            ));
        }
        if let Some(instance) = instance_type {
            settings.push((
                "instanceType".to_string(),
                TsExpr::Lit(TsLit::Str(instance.clone())),
            ));
        }
        settings.push((
            "forward".to_string(),
            TsExpr::array(
                forward
                    .iter()
                    .map(|name| TsExpr::Lit(TsLit::Str(name.clone())))
                    .collect(),
            ),
        ));
        program.push(TsStmt::decl(
            TsDecl::Export(Box::new(TsDecl::ConstDecl {
                name: class_name.clone(),
                ty: None,
                init: TsExpr::Call {
                    callee: Box::new(TsExpr::Ident("__containerClass".to_string())),
                    args: vec![TsExpr::object(settings)],
                },
            })),
            None,
        ));
    }
    Some(program)
}
